function particlesAt(x,y,z,color,n=12){for(let i=0;i<n;i++)particles.push({x,y,z,vx:rand(-2,2),vy:rand(-1,2),vz:rand(-2,2),life:rand(.3,.8),size:rand(1,4),color})}
function fire(){if(!active||over||player.reload>0||player.fire>.14)return;if(player.ammo<=0){player.reload=1.1;return}player.ammo--;player.fire=.22;screenShake=1.8;let best=null,bestD=20;for(let e of enemies){let dx=e.x-player.x,dz=e.z-player.z,d=Math.hypot(dx,dz),a=Math.atan2(dx,dz);let diff=Math.atan2(Math.sin(a-player.yaw),Math.cos(a-player.yaw));if(Math.abs(diff)<.12&&d<bestD){best=e;bestD=d}}
 if(best){best.hp--;best.flash=.12;particlesAt(best.x,1.1,best.z,'#54f4e7',5);if(best.hp<=0){particlesAt(best.x,1,best.z,best.big?'#ff4d85':'#54f4e7',20);enemies.splice(enemies.indexOf(best),1);player.score+=best.big?500:250;player.kills++;if(Math.random()<.24)pickups.push({x:best.x,z:best.z,t:rand(0,9)});if(enemies.length===0)waveCleared()}}
}
