function update(dt){elapsed+=dt;player.fire=Math.max(0,player.fire-dt);player.reload=Math.max(0,player.reload-dt);player.dash=Math.max(0,player.dash-dt);player.invuln=Math.max(0,player.invuln-dt);screenShake=Math.max(0,screenShake-dt*9);toastTimer-=dt;if(toastTimer<=0)ui.toast.style.opacity='0';if(spawnTimer>0){spawnTimer-=dt;if(spawnTimer<=0)spawnWave()}
 let forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0)+touchMove.y;let side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0)+touchMove.x;let mag=Math.hypot(forward,side)||1;forward/=mag;side/=mag;let speed=player.dash>0?9:5.1;let nx=player.x+(Math.sin(player.yaw)*forward+Math.cos(player.yaw)*side)*speed*dt,nz=player.z+(Math.cos(player.yaw)*forward-Math.sin(player.yaw)*side)*speed*dt;
