const obstacles=[{x:0,z:-14,w:30,d:.65},{x:0,z:14,w:30,d:.65},{x:-14,z:0,w:.65,d:28},{x:14,z:0,w:.65,d:28},...[-7,7].flatMap(x=>[-6,6].map(z=>({x,z,w:1.7,d:1.7}))),{x:-2,z:-9,w:1.7,d:1.7},{x:2,z:9,w:1.7,d:1.7},{x:-10,z:0,w:1.7,d:1.7},{x:10,z:0,w:1.7,d:1.7},{x:0,z:0,w:2.4,d:2.4}];
function endGame(win){if(over)return;over=true;active=false;document.exitPointerLock?.();ui.hud.style.display='none';ui.overlay.classList.remove('hide');ui.title.innerHTML=win?'PROTOCOL<span>RESTORED</span>':'SYSTEM<span>BREACHED</span>';ui.subtitle.textContent=win?'SECTOR 07 — EXTRACTION CONFIRMED':'CONNECTION LOST // OPERATOR DOWN';ui.description.innerHTML=win?`You cleared the rogue defense grid. <b>${player.kills} sentinels decommissioned · ${String(player.score).padStart(4,'0')} data recovered.</b> The city is yours again.`:`The sentinels overwhelmed your defenses. <b>${player.kills} sentinels decommissioned · ${String(player.score).padStart(4,'0')} data recovered.</b> Reboot and breach the sector again.`;ui.start.textContent='RUN IT BACK  ↗';}
function startGame(){player.x=0;player.z=10;player.yaw=0;player.pitch=0;player.hp=100;player.ammo=12;player.score=0;player.kills=0;player.wave=1;player.fire=0;player.reload=0;player.dash=0;player.invuln=0;enemies.length=0;shots.length=0;particles.length=0;pickups.length=0;spawnTimer=0;exitOpen=false;over=false;elapsed=0;ui.title.innerHTML='BROKEN<span>PROTOCOL</span>';ui.hud.style.display='block';ui.overlay.classList.add('hide');active=true;spawnWave();updateUI();if(innerWidth>700)canvas.requestPointerLock?.()}
let touchMove={x:0,y:0},stickOn=false,stickCenter={x:0,y:0};
ui.start.addEventListener('click',startGame);canvas.addEventListener('click',()=>{if(active&&innerWidth>700&&!document.pointerLockElement)canvas.requestPointerLock?.();else if(active)fire()});document.addEventListener('mousemove',e=>{if(active&&document.pointerLockElement){player.yaw+=e.movementX*.0026;player.pitch=clamp(player.pitch-e.movementY*.0018,-.4,.4)}});
document.addEventListener('keydown',e=>{keys[e.code]=true;if(['Space','ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.code))e.preventDefault();if(e.code==='Space')fire();if(e.code==='ShiftLeft'||e.code==='ShiftRight')dash();if(e.code==='KeyR'&&active&&player.ammo<12&&player.reload<=0)player.reload=1.1;if(e.code==='Escape'&&active){active=false;ui.hud.style.display='none';ui.overlay.classList.remove('hide');ui.title.innerHTML='BREACH<span>PAUSED</span>';ui.subtitle.textContent='OPERATOR STANDING BY';ui.description.innerHTML='The rogue grid is still hunting. <b>Resume your breach when ready.</b>';ui.start.textContent='RESUME BREACH  ↗';ui.start.onclick=()=>{ui.start.onclick=null;ui.start.addEventListener('click',startGame,{once:true});startGame()}}});document.addEventListener('keyup',e=>keys[e.code]=false);
// Touch stick and drag-to-look controls
ui.stick.addEventListener('pointerdown',e=>{stickOn=true;ui.stick.setPointerCapture(e.pointerId);const r=ui.stick.getBoundingClientRect();stickCenter={x:r.left+r.width/2,y:r.top+r.height/2};moveStick(e)});ui.stick.addEventListener('pointermove',e=>{if(stickOn)moveStick(e)});['pointerup','pointercancel'].forEach(ev=>ui.stick.addEventListener(ev,()=>{stickOn=false;touchMove={x:0,y:0};ui.nub.style.transform='translate(0,0)'}));function moveStick(e){let dx=e.clientX-stickCenter.x,dy=e.clientY-stickCenter.y,l=Math.hypot(dx,dy),m=34;if(l>m){dx*=m/l;dy*=m/l}touchMove={x:dx/m,y:-dy/m};ui.nub.style.transform=`translate(${dx}px,${dy}px)`}
let lookPointer=null;canvas.addEventListener('pointerdown',e=>{if(innerWidth<=700&&active){lookPointer=e.pointerId;canvas.setPointerCapture(e.pointerId)}});canvas.addEventListener('pointermove',e=>{if(innerWidth<=700&&active&&e.pointerId===lookPointer){player.yaw+=e.movementX*.006;player.pitch=clamp(player.pitch-e.movementY*.004,-.4,.4)}});canvas.addEventListener('pointerup',e=>{if(e.pointerId===lookPointer)lookPointer=null});ui.fire.addEventListener('pointerdown',e=>{e.preventDefault();fire()});ui.dash.addEventListener('pointerdown',e=>{e.preventDefault();dash()});
let last=performance.now();function loop(now){let dt=Math.min(.04,(now-last)/1000);last=now;if(active)update(dt);draw();requestAnimationFrame(loop)}requestAnimationFrame(loop);
})();
</script>
</body>
</html>

