function castRay(angle){const a=areas[game.area],m=a.map,dx=Math.cos(angle),dy=Math.sin(angle);let mx=Math.floor(game.x),my=Math.floor(game.y),sdx=Math.abs(1/(dx||1e-9)),sdy=Math.abs(1/(dy||1e-9)),sx,sy,side;if(dx<0){sx=-1;var vx=(game.x-mx)*sdx}else{sx=1;var vx=(mx+1-game.x)*sdx}if(dy<0){sy=-1;var vy=(game.y-my)*sdy}else{sy=1;var vy=(my+1-game.y)*sdy}let tile='.';for(let i=0;i<80;i++){if(vx<vy){vx+=sdx;mx+=sx;side=0}else{vy+=sdy;my+=sy;side=1}tile=m[my]?.[mx]||'#';if(tile!==' .'.trim())break;}let d=(side===0?vx-sdx:vy-sdy);return{d:Math.max(.05,d*Math.cos(angle-game.angle)),side,tile,mx,my,hit:(side===0?game.y+d*dy:game.x+d*dx)%1};}
function render(){const w=W,h=H,horizon=h*.47,cols=Math.ceil(w/2),step=w/cols,depth=[];let sky=ctx.createLinearGradient(0,0,0,horizon);sky.addColorStop(0,game.time>19||game.time<5?'#070a0d':'#39403e');sky.addColorStop(1,game.time>19||game.time<5?'#1a2022':'#73756b');ctx.fillStyle=sky;ctx.fillRect(0,0,w,horizon);let floor=ctx.createLinearGradient(0,horizon,0,h);floor.addColorStop(0,'#383a35');floor.addColorStop(.45,'#212522');floor.addColorStop(1,'#0b0e0d');ctx.fillStyle=floor;ctx.fillRect(0,horizon,w,h-horizon);
 // Depth-tested ray-cast walls and perspective floor seams.
 for(let i=0;i<cols;i++){const x=i*step,ray=game.angle+(i/cols-.5)*1.12,r=castRay(ray),d=r.d;depth[i]=d;const wh=Math.min(h*2,h*.9/d),top=horizon-wh*.5;let shade=clamp(1.05-d/15,.16,.9)*(r.side?.78:1);if(r.tile==='T'){ctx.fillStyle=`rgb(${Math.floor(13*shade)},${Math.floor(20*shade)},${Math.floor(18*shade)})`;ctx.fillRect(x,top,step+1,wh);ctx.fillStyle=`rgba(92,105,82,${shade*.35})`;ctx.fillRect(x,top+wh*.22,step+1,wh*.06)}else{let base=r.tile==='D'?'#51443b':r.tile==='R'?'#463f37':'#55544d';ctx.fillStyle=base;ctx.fillRect(x,top,step+1,wh);ctx.fillStyle=`rgba(8,10,9,${1-shade})`;ctx.fillRect(x,top,step+1,wh);let seam=(Math.floor(r.hit*10)%2===0);if(seam&&d<9){ctx.fillStyle=`rgba(160,146,118,${shade*.11})`;ctx.fillRect(x,top+wh*.1,step+1,Math.max(1,wh*.015));if(wh>80){ctx.fillStyle=`rgba(190,171,126,${shade*.15})`;ctx.fillRect(x,top+wh*.31,step+1,wh*.12);ctx.fillStyle=`rgba(11,15,14,${shade*.8})`;ctx.fillRect(x,top+wh*.33,step+1,wh*.09)}}ctx.fillStyle=`rgba(0,0,0,${clamp(d/30,.05,.46)})`;ctx.fillRect(x,top,step+1,wh);}
 // floor perspective streaks
 if(i%8===0){ctx.strokeStyle=`rgba(151,151,131,${clamp(.05/d,.003,.035)})`;ctx.beginPath();ctx.moveTo(x,horizon);ctx.lineTo(w*.5+(x-w*.5)*7,h);ctx.stroke();}}
 drawWorldSprites(depth,cols,step,horizon);drawAtmosphere();drawHud();}
function drawWorldSprites(depth,cols,step,horizon){const a=areas[game.area];const list=a.objects.filter(o=>!o.hidden).map(o=>({o,d:dist(game,o)})).filter(s=>s.d<19).sort((a,b)=>b.d-a.d);for(const s of list){const o=s.o,angle=Math.atan2(o.y-game.y,o.x-game.x)-game.angle;let da=Math.atan2(Math.sin(angle),Math.cos(angle));if(Math.abs(da)>0.78)continue;const sx=W/2+Math.tan(da)*W*.83,d=s.d,scale=Math.min(H*.7,H*.53/d),base=H*.47+scale*.48,ix=clamp(Math.floor(sx/(W/cols)),0,cols-1);if(depth[ix]<d-.2)continue;drawSprite(o,sx,base,scale,d);}}
function polygon(points,color){ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(points[0][0],points[0][1]);for(let i=1;i<points.length;i++)ctx.lineTo(points[i][0],points[i][1]);ctx.closePath();ctx.fill();}
function drawSprite(o,x,b,s,d){const a=areas[game.area],scl=clamp(s,10,190),head=scl*.19,body=scl*.52;if(o.type==='npc'||o.type==='stalker'){let ghost=o.type==='stalker'||o.personality==='uneasy',c=o.role==='child'?'#7b2828':ghost?'#555c56':o.role==='police'?'#333d3a':'#777365';if(o.type==='stalker'&&Math.sin(game.elapsed*2)>0){ctx.globalAlpha=.42;}polygon([[x-scl*.12,b-body],[x-scl*.18,b-head],[x-scl*.1,b-body-head],[x+scl*.1,b-body-head],[x+scl*.19,b-head],[x+scl*.14,b-body]],c);polygon([[x-head*.62,b-body-head],[x-head*.5,b-body-head-head],[x+head*.5,b-body-head-head],[x+head*.68,b-body-head],[x+head*.55,b-body]],ghost?'#9b9b87':'#9a8d7a');ctx.fillStyle='#171715';ctx.fillRect(x-scl*.13,b-scl*.09,scl*.09,scl*.09);ctx.fillRect(x+scl*.03,b-scl*.09,scl*.09,scl*.09);ctx.globalAlpha=1;if(o.type==='stalker'){ctx.fillStyle='rgba(0,0,0,.2)';ctx.beginPath();ctx.ellipse(x,b,scl*.5,scl*.09,0,0,7);ctx.fill();}}
 else if(o.type==='clue'){ctx.fillStyle=o.clue==='notice'?'#d0c8b0':o.clue==='voice'?'#514e48':'#a59577';ctx.fillRect(x-scl*.14,b-scl*.54,scl*.28,scl*.34);ctx.fillStyle='#242824';for(let j=0;j<3;j++)ctx.fillRect(x-scl*.1,b-scl*.46+j*scl*.07,scl*.2,scl*.012);}
 else if(o.type==='door'||o.type==='back'){ctx.fillStyle='#302d29';ctx.fillRect(x-scl*.24,b-scl*.72,scl*.48,scl*.72);ctx.fillStyle='#6b6558';ctx.fillRect(x-scl*.19,b-scl*.66,scl*.38,scl*.66);ctx.fillStyle='#252725';ctx.fillRect(x-scl*.15,b-scl*.61,scl*.3,scl*.59);ctx.fillStyle='#b9a67c';ctx.fillRect(x+scl*.09,b-scl*.34,scl*.025,scl*.025);}
