const { createRequire } = require('node:module');
const runtimeRequire = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = runtimeRequire('playwright');
(async () => {
  const browser = await chromium.launch({ channel: 'chromium', headless: false, args: ['--enable-gpu', '--ignore-gpu-blocklist', '--enable-unsafe-webgpu', '--use-angle=vulkan', '--enable-features=Vulkan', '--use-vulkan=swiftshader', '--use-webgpu-adapter=swiftshader', '--disable-vulkan-surface'] });
  const page = await browser.newPage({ viewport: {width:390,height:844} });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://127.0.0.1:8765/', {waitUntil:'load'});
  await page.locator('#startButton').click();
  await page.evaluate(() => { const g = window.__THE_TOWN_TEST__.game; g.sanity = 0; g.flags.photo = true; });
  await page.waitForTimeout(46000);
  const state = await page.evaluate(() => ({intensity: window.__THE_TOWN_TEST__.game.hallucination, memory: window.__THE_TOWN_TEST__.game.flags.photo, sanity: window.__THE_TOWN_TEST__.game.sanity}));
  if (state.intensity < 45) throw new Error(`Hallucination did not escalate as expected: ${JSON.stringify(state)}`);
  await page.screenshot({path:'/tmp/opencode/town-hallucination-390.jpg',type:'jpeg',quality:85});
  await page.locator('[data-action="i"]').click();
  await page.getByRole('button', {name:/Take a calming caplet \(3 left\)/}).click();
  const after = await page.evaluate(() => ({intensity: window.__THE_TOWN_TEST__.game.hallucination, sanity: window.__THE_TOWN_TEST__.game.sanity, caplets: window.__THE_TOWN_TEST__.game.caplets}));
  if (after.intensity !== 0 || after.sanity !== 12 || after.caplets !== 2) throw new Error(`Treatment failed: ${JSON.stringify(after)}`);
  console.log(`Mobile hallucination progression verified: intensity ${state.intensity.toFixed(1)} after 46s; caplet cleared it and restored sanity; remaining caplets=${after.caplets}; page errors=${errors.length}`);
  await browser.close();
})().catch(e => { console.error(e); process.exit(1); });
